            s['density_g_per_ml']=round(rng.uniform(0.9,1.3),3)
        return s
    while len(cases)<24:
        solute,mm=rng.choice(solutes)
        mm_val=mm if rng.random()<0.7 else None
        if rng.random()<0.4:
            s=mk(solute)
            v=rng.randint(1,s['volume_ml'])
